exec(open('/tmp/fitcov.py').read().split("best=[]")[0])
import math
def bary_fill(sp,shift):
    (ax,ay),(bx,by),(cx,cy)=sp
    # tinyrenderer cross method with float
    out=set()
    xmin=min(ax,bx,cx); xmax=max(ax,bx,cx); ymin=min(ay,by,cy); ymax=max(ay,by,cy)
    # clamp like tinyrenderer: bboxmin max(0,..), bboxmax min(W-1,..)
    xmin=max(0,xmin); ymin=max(0,ymin); xmax=min(W-1,xmax); ymax=min(H-1,ymax)
    for yy in range(ymin,ymax+1):
        for xx in range(xmin,xmax+1):
            # u = cross((cx-ax,bx-ax,ax-xx),(cy-ay,by-ay,ay-yy))
            ux = (bx-ax)*(ay-yy) - (ax-xx)*(by-ay)
            uy = (ax-xx)*(cy-ay) - (cx-ax)*(ay-yy)
            uz = (cx-ax)*(by-ay) - (bx-ax)*(cy-ay)
            if abs(uz)<1: continue
            b1=1-(ux+uy)/uz; b2=uy/uz; b3=ux/uz
            if b1<0 or b2<0 or b3<0: continue
            X=xx+shift; Y=yy
            if X>=W: X-=W; Y+=1
            out.add((X,Y))
    return out
def make_sp(pts,formula):
    sp=[]
    for x,y,z in pts:
        if formula=='s1': sp.append((int(40-40*x),int(20-20*y)))
        elif formula=='s2': sp.append((80-int((x+1)*40),40-int((y+1)*20)))
        elif formula=='s1r': sp.append((round(40-40*x),round(20-20*y)))
        elif formula=='s2r': sp.append((80-round((x+1)*40),40-round((y+1)*20)))
        elif formula=='s1f': sp.append((math.floor(40-40*x),math.floor(20-20*y)))
        elif formula=='s1c': sp.append((math.ceil(40-40*x),math.ceil(20-20*y)))
        elif formula=='half': sp.append((int(40-40*x+0.5),int(20-20*y+0.5)))
    return sp
for formula in ['s1','s2','s1r','s2r','s1f','s1c','half']:
 for shift in [0,1]:
    tot=sum(len(bary_fill(make_sp(t,formula),shift)^r) for t,r in zip(tris,refs))
    print(formula,shift,tot)
