import sys; sys.path.insert(0,'/tmp')
exec(open('/tmp/fitcov.py').read().split("best=[]")[0])
import math
def screen(pts,ox=0,oy=0):
    return [(-x*40+40+ox,-y*20+20+oy) for x,y,z in pts]
def scanline(pts,mode):
    ox,oy,xcast,ycast,incl = mode
    t=sorted(screen(pts,ox,oy),key=lambda p:p[1])
    (x0,y0),(x1,y1),(x2,y2)=t
    out=set()
    total=y2-y0
    if total==0: return out
    def C(v):
        return int(v) if xcast=='int' else (round(v) if xcast=='round' else math.floor(v))
    i=0
    while i < total:
        second = i > (y1-y0) or y1==y0
        seg = (y2-y1) if second else (y1-y0)
        if seg==0:
            i+=1; continue
        alpha=i/total
        beta=(i-((y1-y0) if second else 0))/seg
        Ax=x0+(x2-x0)*alpha; Ay=y0+(y2-y0)*alpha
        if second: Bx=x1+(x2-x1)*beta; By=y1+(y2-y1)*beta
        else: Bx=x0+(x1-x0)*beta; By=y0+(y1-y0)*beta
        if Ax>Bx: Ax,Bx=Bx,Ax
        yy = int(y0+i) if ycast=='int' else round(y0+i)
        xa=C(Ax); xb=C(Bx)
        rng=range(xa,xb+1) if incl else range(xa,xb)
        for xx in rng:
            if 0<=xx<W and 0<=yy<H: out.add((xx,yy))
        i+=1
    return out
