import os, sys, time, select, fcntl, termios, struct, subprocess
master, slave = os.openpty()
def setsize(c,r): fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',r,c,0,0))
setsize(40,10)
p=subprocess.Popen(["./executable","-b","assets/test_model.obj"], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
os.close(slave); os.set_blocking(master,False)
def collect(dur):
    out=b''; end=time.time()+dur
    while time.time()<end:
        r,_,_=select.select([master],[],[],0.02)
        if master in r:
            try: d=os.read(master,65536)
            except OSError: break
            if not d: break
            out+=d
    return out
o1=collect(0.5)
# resize via master ioctl as well (slave fd closed; use master)
fcntl.ioctl(master, termios.TIOCSWINSZ, struct.pack('HHHH',30,100,0,0))
o2=collect(0.5)
try: os.write(master,b'q')
except: pass
try: print("status",p.wait(timeout=1))
except: p.kill(); print("killed",p.wait())
for name,o in [("before",o1),("after",o2)]:
    frames=o.split(b'\x1b[1;1H')
    print(name,"frames",len(frames)-1,"frame lens sample",[len(f) for f in frames[1:4]])
PY
