import sys; sys.path.insert(0,'/tmp'); from safe import run_ref
import re
pat=re.compile(r'\x1b\[48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m(.*?)\x1b\[49m\x1b\[39m',re.S)
for model in ["assets/test_model.obj","assets/cube.stl","assets/part.stl"]:
    for (w,h) in [(40,20),(80,40),(33,17)]:
        for rot in [[],["-x","0.7"],["-y","1.3"],["-z","2.1"],["-x","1","-y","2","-z","0.5"]]:
            r=run_ref([model,"image","-w",str(w),"-h",str(h)]+rot)
            ms=list(pat.finditer(r.stdout))
            spaces=sum(1 for m in ms if m.groups()[3:6]!=('0','0','0') and m.group(7)==' ')
            total=sum(1 for m in ms if m.groups()[3:6]!=('0','0','0'))
            if spaces: print(model,w,h,rot,"SPACES",spaces,"/",total)
print("done - only printed cases with space-shaded pixels")
