use std::ops::{Add, Div, Mul, Sub};

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Vec3 {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

impl Vec3 {
    pub fn new(x: f32, y: f32, z: f32) -> Vec3 {
        Vec3 { x, y, z }
    }
    pub fn cross(self, other: Vec3) -> Vec3 {
        Vec3::new(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x,
        )
    }
    pub fn dot(self, other: Vec3) -> f32 {
        self.x * other.x + self.y * other.y + self.z * other.z
    }
    pub fn length(self) -> f32 {
        (self.x * self.x + self.y * self.y + self.z * self.z).sqrt()
    }
    pub fn normalized(self) -> Vec3 {
        let l = self.length();
        Vec3::new(self.x / l, self.y / l, self.z / l)
    }
    pub fn rotate(self, rotation: (f32, f32, f32)) -> Vec3 {
        let (xrot, yrot, zrot) = rotation;
        let mut v = self;
        // rotate around X
        let (s, c) = xrot.sin_cos();
        v = Vec3::new(v.x, v.y * c - v.z * s, v.y * s + v.z * c);
        // rotate around Y
        let (s, c) = yrot.sin_cos();
        v = Vec3::new(v.x * c + v.z * s, v.y, -v.x * s + v.z * c);
        // rotate around Z (note sign convention observed in the reference)
        let (s, c) = zrot.sin_cos();
        v = Vec3::new(v.x * c + v.y * s, -v.x * s + v.y * c, v.z);
        v
    }
}

impl Add for Vec3 {
    type Output = Vec3;
    fn add(self, other: Vec3) -> Vec3 {
        Vec3::new(self.x + other.x, self.y + other.y, self.z + other.z)
    }
}
impl Sub for Vec3 {
    type Output = Vec3;
    fn sub(self, other: Vec3) -> Vec3 {
        Vec3::new(self.x - other.x, self.y - other.y, self.z - other.z)
    }
}
impl Mul<f32> for Vec3 {
    type Output = Vec3;
    fn mul(self, k: f32) -> Vec3 {
        Vec3::new(self.x * k, self.y * k, self.z * k)
    }
}
impl Div<f32> for Vec3 {
    type Output = Vec3;
    fn div(self, k: f32) -> Vec3 {
        Vec3::new(self.x / k, self.y / k, self.z / k)
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Triangle {
    pub a: Vec3,
    pub b: Vec3,
    pub c: Vec3,
    pub color: (u8, u8, u8),
}

pub struct Material {
    pub name: String,
    pub diffuse: [f32; 3],
}

// A triangle as produced by the OBJ parser: indices into the position list
// are already resolved to points.
pub struct RawTriangle {
    pub pts: [Vec3; 3],
    pub material_id: Option<usize>,
}

pub struct Model {
    pub triangles: Vec<Triangle>,
}

fn diffuse_to_color(diffuse: [f32; 3]) -> (u8, u8, u8) {
    (
        (diffuse[0] * 255.0) as u8,
        (diffuse[1] * 255.0) as u8,
        (diffuse[2] * 255.0) as u8,
    )
}

impl Model {
    pub fn new() -> Model {
        Model { triangles: Vec::new() }
    }

    pub fn add_obj_triangles(&mut self, raw: Vec<RawTriangle>, materials: &[Material]) {
        for tri in raw {
            let color = if materials.is_empty() {
                (1, 1, 1)
            } else {
                let material = &materials[tri.material_id.unwrap()];
                diffuse_to_color(material.diffuse)
            };
            self.triangles.push(Triangle { a: tri.pts[0], b: tri.pts[1], c: tri.pts[2], color });
        }
    }

    pub fn add_stl_triangles(&mut self, raw: Vec<[Vec3; 3]>) {
        for pts in raw {
            self.triangles.push(Triangle { a: pts[0], b: pts[1], c: pts[2], color: (255, 255, 0) });
        }
    }

    // The largest (signed) coordinate component over all referenced vertices,
    // starting from 0.0.  All points are divided by this value.
    pub fn scale_factor(&self) -> f32 {
        let mut max = 0.0f32;
        for tri in &self.triangles {
            for p in [tri.a, tri.b, tri.c] {
                if p.x > max { max = p.x; }
                if p.y > max { max = p.y; }
                if p.z > max { max = p.z; }
            }
        }
        max
    }
}
