use crate::geometry::{Triangle, Vec3};

pub const PALETTE: [char; 10] = [' ', '.', ':', '-', '=', '+', '*', '#', '%', '@'];

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Pixel {
    pub character: char,
    pub foreground: (u8, u8, u8),
    pub background: (u8, u8, u8),
}

impl Pixel {
    pub fn new(character: char, foreground: (u8, u8, u8)) -> Pixel {
        Pixel { character, foreground, background: (25, 25, 25) }
    }
}

impl Default for Pixel {
    fn default() -> Pixel {
        Pixel::new(' ', (0, 0, 0))
    }
}

pub struct Rasterizer {
    pub width: usize,
    pub height: usize,
    pub color: bool,
    pub buffer: Vec<Pixel>,
    zbuffer: Vec<f32>,
}

impl Rasterizer {
    pub fn new(width: usize, height: usize, color: bool) -> Rasterizer {
        let size = (width + 1) * height;
        Rasterizer {
            width,
            height,
            color,
            buffer: vec![Pixel::default(); size],
            zbuffer: vec![f32::NEG_INFINITY; size],
        }
    }

    fn screen_point(&self, p: Vec3) -> (f32, f32) {
        let w = self.width as f32;
        let h = self.height as f32;
        let s = if w < 2.0 * h { w } else { 2.0 * h };
        (w / 2.0 - p.x * (s / 2.0), h / 2.0 - p.y * (s / 4.0))
    }

    pub fn draw_triangle(&mut self, tri: &Triangle, rotation: (f32, f32, f32), scale: f32) {
        // Original (pre-scale) rotated points, used only for an edge case
        // when the buffer is empty (0x0 rasterizer).
        let orig_a = tri.a.rotate(rotation);
        let orig_b = tri.b.rotate(rotation);
        let orig_c = tri.c.rotate(rotation);
        if self.buffer.is_empty() {
            if orig_a.y > 1.0 || orig_b.y > 1.0 || orig_c.y > 1.0 {
                self.buffer[1] = Pixel::default();
            } else {
                return;
            }
        }
        let a = orig_a / scale;
        let b = orig_b / scale;
        let c = orig_c / scale;

        let normal = (b - a).cross(c - a).normalized();
        let intensity = normal.z;

        let (ax, ay) = self.screen_point(a);
        let (bx, by) = self.screen_point(b);
        let (cx, cy) = self.screen_point(c);

        let width = self.width as i32;
        let height = self.height as i32;

        let mut y_start = ay.min(by).min(cy).ceil() as i32;
        let mut y_end = ay.max(by).max(cy).ceil() as i32;
        if y_start < 1 { y_start = 1; }
        if y_end > height - 1 { y_end = height - 1; }

        let mut vx_start = (ax.min(bx).min(cx) / 2.0).ceil() as i32;
        let mut vx_end = (ax.max(bx).max(cx) / 2.0).ceil() as i32;
        if vx_start < 1 { vx_start = 1; }
        if vx_end > width - 1 { vx_end = width - 1; }

        let pixel = Pixel::new(
            PALETTE[(intensity * 10.0) as usize % 10],
            tri.color,
        );
        let newline = Pixel::new('\n', (0, 0, 0));

        for y in y_start..y_end {
            for vx in vx_start..=vx_end {
                let px = (2 * vx) as f32;
                let py = y as f32;
                let u = Vec3::new(cx - ax, bx - ax, ax - px)
                    .cross(Vec3::new(cy - ay, by - ay, ay - py));
                if u.z.abs() < 1.0 {
                    continue;
                }
                let la = 1.0 - (u.x + u.y) / u.z;
                let lb = u.y / u.z;
                let lc = u.x / u.z;
                if la < 0.0 || lb < 0.0 || lc < 0.0 {
                    continue;
                }
                if intensity <= 0.0 {
                    continue;
                }
                let z = la * a.z + lb * b.z + lc * c.z;
                let idx = (y * width + 2 * vx) as usize;
                if idx < self.zbuffer.len() && z > self.zbuffer[idx] {
                    self.zbuffer[idx] = z;
                    self.buffer[idx] = pixel;
                    if idx + 1 < self.zbuffer.len() {
                        self.zbuffer[idx + 1] = z;
                        self.buffer[idx + 1] = pixel;
                    }
                }
            }
            let nidx = (y * width + 1) as usize;
            if nidx < self.buffer.len() {
                self.buffer[nidx] = newline;
            }
        }
    }

    pub fn draw_model(&mut self, triangles: &[Triangle], rotation: (f32, f32, f32), scale: f32) {
        for tri in triangles {
            self.draw_triangle(tri, rotation, scale);
        }
    }

    fn pixel_color_string(&self, pixel: &Pixel) -> String {
        format!(
            "\x1b[48;2;{};{};{}m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m",
            pixel.background.0, pixel.background.1, pixel.background.2,
            pixel.foreground.0, pixel.foreground.1, pixel.foreground.2,
            pixel.character
        )
    }

    pub fn render_color(&self) -> String {
        let mut s = String::new();
        for pixel in &self.buffer {
            s.push_str(&self.pixel_color_string(pixel));
        }
        s
    }

    pub fn render_plain(&self) -> String {
        let mut s = String::new();
        for pixel in &self.buffer {
            s.push(pixel.character);
        }
        s
    }

    pub fn render_web(&self) -> String {
        let mut s = String::new();
        for pixel in &self.buffer {
            s.push_str(&format!(
                "<span style=\"color:rgb({},{},{})\">{ }",
                pixel.foreground.0, pixel.foreground.1, pixel.foreground.2, pixel.character
            ));
        }
        s
    }

    pub fn render_terminal_color(&self) -> String {
        let mut s = String::new();
        for pixel in self.buffer.iter().take(self.width * self.height) {
            let mut p = *pixel;
            if p.character == '\n' {
                p.character = ' ';
            }
            s.push_str(&self.pixel_color_string(&p));
        }
        s
    }

    pub fn render_terminal_plain(&self) -> String {
        let mut s = String::new();
        for pixel in self.buffer.iter().take(self.width * self.height) {
            if pixel.character == '\n' {
                s.push(' ');
            } else {
                s.push(pixel.character);
            }
        }
        s
    }
}
