                        Some(i) => i,
                        None => return Err(LoadError::FaceVertexIndexOutOfBounds),
                    };
                    if parts.len() >= 2 && !parts[1].is_empty() {
                        let ti: i64 = match parts[1].parse() {
                            Ok(v) => v,
                            Err(_) => return Err(LoadError::FaceParseError),
                        };
                        if get_index(ti, texcoords_count).is_none() {
                            return Err(LoadError::FaceTexcoordIndexOutOfBounds);
                        }
                    }
                    if parts.len() >= 3 && !parts[2].is_empty() {
                        let ni: i64 = match parts[2].parse() {
                            Ok(v) => v,
                            Err(_) => return Err(LoadError::FaceParseError),
                        };
                        if get_index(ni, normals_count).is_none() {
                            return Err(LoadError::FaceNormalIndexOutOfBounds);
                        }
                    }
                    if parts.len() == 2 && parts[1].is_empty() {
                        return Err(LoadError::FaceParseError);
                    }
                    if has_colors && pi >= colors.len() {
                        return Err(LoadError::FaceVertexColorIndexOutOfBounds);
                    }
                    face.push(pi);
                }
                if face.len() >= 3 {
                    for i in 1..face.len() - 1 {
                        let a = positions[face[0]];
                        let b = positions[face[i]];
                        let c = positions[face[i + 1]];
                        triangles.push(RawTriangle {
                            pts: [
                                Vec3::new(a[0], a[1], a[2]),
                                Vec3::new(b[0], b[1], b[2]),
                                Vec3::new(c[0], c[1], c[2]),
                            ],
                            material_id: current_material,
                        });
                    }
                }
            }
            "mtllib" => {
                if tokens.len() < 2 {
                    return Err(LoadError::MaterialParseError);
                }
                for name in &tokens[1..] {
                    let mtl_path = base_dir.join(name);
                    let had_any = !materials.is_empty() || mat_err.is_none() && false;
                    match load_mtl_file(&mtl_path, &mut materials, &mut mat_map) {
                        Ok(()) => {}
                        Err(e) => {
                            if materials.is_empty() {
                                mat_err = Some(e);
                                break;
                            } else if !had_any {
                                // keep going like tobj when some materials already loaded
                            }
                        }
                    }
                }
            }
            "usemtl" => {
                if tokens.len() < 2 {
                    return Err(LoadError::MaterialParseError);
                }
                let name = tokens[1..].join(" ");
                current_material = mat_map.get(&name).copied();
            }
            _ => {}
        }
        let _ = &text;
    }

    let materials_result = match mat_err {
        Some(e) => Err(e),
        None => Ok(materials),
    };
    Ok((triangles, materials_result))
}
