                materials.push(Material { name: name.clone(), diffuse: [0.0, 0.0, 0.0] });
                mat_map.insert(name, idx);
            }
            "Kd" | "Ka" | "Ks" | "Ke" => {
                let vals = match parse_f32s(&tokens[1..], 3) {
                    Some(v) => v,
                    None => return Err(LoadError::MaterialParseError),
                };
                if tokens[0] == "Kd" {
                    if let Some(m) = materials.last_mut() {
                        m.diffuse = [vals[0], vals[1], vals[2]];
                    }
                }
            }
            "Ns" | "Ni" | "d" | "Tr" | "illum" => {
                if tokens.len() < 2 || tokens[1].parse::<f32>().is_err() {
                    return Err(LoadError::MaterialParseError);
                }
            }
            _ => {}
        }
    }
