// Returns (triangles, materials-result) mimicking tobj::load_obj.
pub fn load_obj(path: &Path) -> Result<(Vec<RawTriangle>, Result<Vec<Material>, LoadError>), LoadError> {
    let mut file = File::open(path).map_err(|_| LoadError::OpenFileFailed)?;
    let mut text = String::new();
    // tobj reads the file as bytes and parses lines; a read failure (e.g. directory) is ReadError.
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).map_err(|_| LoadError::ReadError)?;
    text = String::from_utf8_lossy(&bytes).into_owned();

    let base_dir: PathBuf = path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from(""));

    let mut positions: Vec<[f32; 3]> = Vec::new();
    let mut normals_count: usize = 0;
    let mut texcoords_count: usize = 0;
    let mut colors: Vec<[f32; 3]> = Vec::new();
    let mut has_colors = false;

    let mut materials: Vec<Material> = Vec::new();
    let mut mat_map: HashMap<String, usize> = HashMap::new();
    let mut mat_err: Option<LoadError> = None;
    let mut current_material: Option<usize> = None;

    let mut triangles: Vec<RawTriangle> = Vec::new();

    for raw_line in text.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let tokens: Vec<&str> = line.split_whitespace().collect();
        if tokens.is_empty() {
            continue;
        }
        match tokens[0] {
            "v" => {
                let rest = &tokens[1..];
                if rest.len() > 3 {
                    has_colors = true;
                }
                let pos = match parse_f32s(rest, 3) {
                    Some(v) => v,
                    None => return Err(LoadError::PositionParseError),
                };
                positions.push([pos[0], pos[1], pos[2]]);
                if rest.len() >= 6 {
                    match parse_f32s(&rest[3..], 3) {
                        Some(c) => colors.push([c[0], c[1], c[2]]),
                        None => return Err(LoadError::VertexColorParseError),
                    }
                }
            }
            "vn" => {
                if parse_f32s(&tokens[1..], 3).is_none() {
                    return Err(LoadError::NormalParseError);
                }
                normals_count += 1;
            }
            "vt" => {
                if parse_f32s(&tokens[1..], 2).is_none() {
                    return Err(LoadError::TexcoordParseError);
                }
                texcoords_count += 1;
            }
            "f" => {
                let ftoks = &tokens[1..];
                if ftoks.is_empty() {
                    return Err(LoadError::FaceParseError);
                }
                let mut face: Vec<usize> = Vec::new();
                for tok in ftoks {
                    let parts: Vec<&str> = tok.split('/').collect();
                    if parts.len() > 3 || parts[0].is_empty() {
                        return Err(LoadError::FaceParseError);
                    }
                    let vi: i64 = match parts[0].parse() {
                        Ok(v) => v,
                        Err(_) => return Err(LoadError::FaceParseError),
                    };
                    let pi = match get_index(vi, positions.len()) {
                        Some(i) => i,
                        None => return Err(LoadError::FaceVertexIndexOutOfBounds),
                    };
                    if parts.len() >= 2 && !parts[1].is_empty() {
                        let ti: i64 = match parts[1].parse() {
                            Ok(v) => v,
                            Err(_) => return Err(LoadError::FaceParseError),
                        };
                        if get_index(ti, texcoords_count).is_none() {
                            return Err(LoadError::FaceTexcoordIndexOutOfBounds);
                        }
                    }
                    if parts.len() >= 3 && !parts[2].is_empty() {
                        let ni: i64 = match parts[2].parse() {
                            Ok(v) => v,
                            Err(_) => return Err(LoadError::FaceParseError),
                        };
                        if get_index(ni, normals_count).is_none() {
                            return Err(LoadError::FaceNormalIndexOutOfBounds);
                        }
                    }
                    if parts.len() == 2 && parts[1].is_empty() {
                        return Err(LoadError::FaceParseError);
                    }
                    if has_colors && pi >= colors.len() {
                        return Err(LoadError::FaceVertexColorIndexOutOfBounds);
                    }
                    face.push(pi);
                }
                if face.len() >= 3 {
                    for i in 1..face.len() - 1 {
                        let a = positions[face[0]];
                        let b = positions[face[i]];
                        let c = positions[face[i + 1]];
                        triangles.push(RawTriangle {
                            pts: [
                                Vec3::new(a[0], a[1], a[2]),
                                Vec3::new(b[0], b[1], b[2]),
                                Vec3::new(c[0], c[1], c[2]),
                            ],
                            material_id: current_material,
                        });
                    }
                }
            }
            "mtllib" => {
                if tokens.len() < 2 {
                    return Err(LoadError::MaterialParseError);
                }
                for name in &tokens[1..] {
                    let mtl_path = base_dir.join(name);
                    let had_any = !materials.is_empty() || mat_err.is_none() && false;
                    match load_mtl_file(&mtl_path, &mut materials, &mut mat_map) {
                        Ok(()) => {}
                        Err(e) => {
                            if materials.is_empty() {
                                mat_err = Some(e);
                                break;
                            } else if !had_any {
                                // keep going like tobj when some materials already loaded
                            }
                        }
                    }
                }
            }
            "usemtl" => {
                if tokens.len() < 2 {
                    return Err(LoadError::MaterialParseError);
                }
                let name = tokens[1..].join(" ");
                current_material = mat_map.get(&name).copied();
            }
            _ => {}
        }
        let _ = &text;
    }

    let materials_result = match mat_err {
        Some(e) => Err(e),
        None => Ok(materials),
    };
    Ok((triangles, materials_result))
}
