            None => return Err(eof_expect("endfacet")),
            Some(l) => l,
        };
        {
            let t: Vec<&str> = l4.split_whitespace().collect();
            if t != ["endfacet"] {
                return Err(io::Error::new(io::ErrorKind::InvalidData, format!("endfacet, got {:?}", t)));
            }
        }
        triangles.push([
            Vec3::new(verts[0][0], verts[0][1], verts[0][2]),
            Vec3::new(verts[1][0], verts[1][1], verts[1][2]),
            Vec3::new(verts[2][0], verts[2][1], verts[2][2]),
        ]);
    }
    Ok(triangles)
}

fn eof_expect(what: &str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, format!("EOF while expecting {}", what))
}

fn next_nonempty(lines: &mut std::str::Lines) -> Option<String> {
    for l in lines.by_ref() {
        if !l.trim().is_empty() {
            return Some(l.trim().to_string());
        }
    }
    None
}
