    if p.inputs.is_empty() {
        let usage = p.usage_for_error(ErrKind::MissingRequired, None);
        err_exit(
            "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
            usage,
        );
    }

    Matches {
        b: p.b_seen,
        yaw: p.yaw,
        pitch: p.pitch,
        roll: p.roll,
        inputs: p.inputs,
        image: if p.in_image {
            Some(ImageMatches {
                b: p.img_b_seen,
                webify: p.img_webify,
                height: p.img_height,
                width: p.img_width,
                yaw: p.img_yaw,
                pitch: p.img_pitch,
                roll: p.img_roll,
            })
        } else {
            None
        },
    }
}

fn is_flag_like(tok: &str) -> bool {
    tok.len() > 1 && tok.starts_with('-')
}

fn mark_used(p: &mut Parser, a: ArgId) {
    let list = if p.in_image { &mut p.used_img } else { &mut p.used_top };
    if !list.contains(&a) {
        list.push(a);
    }
}

fn check_dup(p: &Parser, a: ArgId) {
    let present = match (p.in_image, a) {
        (false, ArgId::Yaw) => p.yaw.is_some() || p.used_top.contains(&a) && p.yaw.is_some(),
        (false, ArgId::Pitch) => p.pitch.is_some(),
        (false, ArgId::Roll) => p.roll.is_some(),
        (true, ArgId::Yaw) => p.img_yaw.is_some(),
        (true, ArgId::Pitch) => p.img_pitch.is_some(),
        (true, ArgId::Roll) => p.img_roll.is_some(),
        (true, ArgId::Webify) => p.img_webify.is_some(),
        (true, ArgId::Height) => p.img_height.is_some(),
        (true, ArgId::Width) => p.img_width.is_some(),
        _ => false,
    };
    // For options given once with no value yet (pending), a second occurrence is also a duplicate in clap;
    // we approximate by checking used-with-value above, plus empty_pending.
    let pending_dup = p.empty_pending.contains(&a);
    if present || pending_dup {
        p.duplicate(a);
    }
}

fn set_value(p: &mut Parser, a: ArgId, v: String) {
    match (p.in_image, a) {
        (false, ArgId::Yaw) => p.yaw = Some(v),
        (false, ArgId::Pitch) => p.pitch = Some(v),
        (false, ArgId::Roll) => p.roll = Some(v),
        (true, ArgId::Yaw) => p.img_yaw = Some(v),
        (true, ArgId::Pitch) => p.img_pitch = Some(v),
        (true, ArgId::Roll) => p.img_roll = Some(v),
        (true, ArgId::Webify) => p.img_webify = Some(v),
        (true, ArgId::Height) => p.img_height = Some(v),
        (true, ArgId::Width) => p.img_width = Some(v),
        _ => {}
    }
}

fn push_positional(p: &mut Parser, tok: &str, after_dashdash: bool, bin: &str) {
    if after_dashdash && !p.in_image && (tok == "image" || tok == "help") {
        // Clap's special error when a subcommand name is used as a positional value after --.
        eprint!(
            "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            tok, tok, bin, tok,
            full_usage_top(bin)
        );
        exit(1);
    }
    if p.in_image {
        err_exit(
            format!("Found argument '{}' which wasn't expected, or isn't valid in this context", tok),
            p.usage_for_error(ErrKind::Unknown, None),
        );
    }
    p.inputs.push(tok.to_string());
}
EOF
