// Canonical arg identifiers
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ArgId {
    B,
    Yaw,
    Pitch,
    Roll,
    Webify,
    Height,
    Width,
}

fn display_arg(a: ArgId) -> &'static str {
    match a {
        ArgId::B => "-b",
        ArgId::Yaw => "--yaw <x>",
        ArgId::Pitch => "--pitch <y>",
        ArgId::Roll => "--roll <z>",
        ArgId::Webify => "--webify <frame count>",
        ArgId::Height => "-h <height>",
        ArgId::Width => "-w <width>",
    }
}

fn arg_error_name(a: ArgId) -> &'static str {
    // Name used in "The argument '<name>' requires a value..." messages.
    match a {
        ArgId::B => "-b",
        ArgId::Yaw => "--yaw <x>",
        ArgId::Pitch => "--pitch <y>",
        ArgId::Roll => "--roll <z>",
        ArgId::Webify => "--webify <frame count>",
        ArgId::Height => "-h <height>",
        ArgId::Width => "-w <width>",
    }
}

const TOP_ORDER: [ArgId; 4] = [ArgId::B, ArgId::Yaw, ArgId::Pitch, ArgId::Roll];
const IMAGE_ORDER: [ArgId; 7] = [
    ArgId::B,
    ArgId::Webify,
    ArgId::Height,
    ArgId::Width,
    ArgId::Yaw,
    ArgId::Pitch,
    ArgId::Roll,
];

fn smart_usage(bin: &str, in_image: bool, used: &[ArgId]) -> String {
    let mut parts: Vec<String> = vec![bin.to_string()];
    if in_image {
        parts.push("image".to_string());
        for a in IMAGE_ORDER.iter() {
            if used.contains(a) || *a == ArgId::Width {
                parts.push(display_arg(*a).to_string());
            }
        }
    } else {
        parts.push("<input filename(s)>...".to_string());
        for a in TOP_ORDER.iter() {
            if used.contains(a) {
                parts.push(display_arg(*a).to_string());
            }
        }
    }
    parts.join(" ")
}

struct Parser {
    bin: String,
    // top-level state
    b_seen: bool,
    yaw: Option<String>,
    pitch: Option<String>,
    roll: Option<String>,
    inputs: Vec<String>,
    used_top: Vec<ArgId>,
    // image state
    in_image: bool,
    img_b_seen: bool,
    img_webify: Option<String>,
    img_height: Option<String>,
    img_width: Option<String>,
    img_yaw: Option<String>,
    img_pitch: Option<String>,
    img_roll: Option<String>,
    used_img: Vec<ArgId>,
    // args that were present but got no value (for missing-required vs empty-value precedence)
    empty_pending: Vec<ArgId>,
    input_before_image: bool,
}

impl Parser {
    fn usage_for_error(&self, kind: ErrKind, offending: Option<ArgId>) -> String {
        // Decide between full and smart usage.
        let (used, in_image) = if self.in_image {
            (self.used_img.clone(), true)
        } else {
            (self.used_top.clone(), false)
        };
        let mut used_all = used.clone();
        if let Some(o) = offending {
            if !used_all.contains(&o) {
                used_all.push(o);
            }
        }
        let required: &[ArgId] = if in_image { &[ArgId::Width] } else { &[] };
        let only_required = used_all.iter().all(|a| required.contains(a));
        match kind {
            ErrKind::Unknown => self.full_usage(),
            ErrKind::MissingRequired => {
                if used.is_empty() {
                    self.full_usage()
                } else {
                    smart_usage(&self.bin, in_image, &used_all)
                }
            }
            ErrKind::EmptyValue | ErrKind::Duplicate => {
                if only_required {
                    self.full_usage()
                } else {
                    smart_usage(&self.bin, in_image, &used_all)
                }
            }
        }
    }

    fn full_usage(&self) -> String {
        if self.in_image {
            full_usage_image(&self.bin, !self.input_before_image)
        } else {
            full_usage_top(&self.bin)
        }
    }

    fn unknown_arg(&self, shown: &str) -> ! {
        err_exit(
            format!("Found argument '{}' which wasn't expected, or isn't valid in this context", shown),
            self.usage_for_error(ErrKind::Unknown, None),
        );
    }

    fn duplicate(&self, a: ArgId) -> ! {
        err_exit(
            format!("The argument '{}' was provided more than once, but cannot be used multiple times", arg_error_name(a)),
            self.usage_for_error(ErrKind::Duplicate, Some(a)),
        );
    }

    fn print_help(&self) -> ! {
        if self.in_image {
            print!("{}", image_help(&self.bin, !self.input_before_image));
        } else {
            print!("{}", top_help(&self.bin));
        }
        exit(0);
    }

    fn print_version(&self) -> ! {
        if self.in_image {
            println!("{}-image ", self.bin);
        } else {
            println!("Sloth 0.1");
        }
        exit(0);
    }
}

#[derive(Clone, Copy, PartialEq)]
enum ErrKind {
    Unknown,
    MissingRequired,
    EmptyValue,
    Duplicate,
}

pub fn parse_args() -> Matches {
    let bin = bin_name();
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut p = Parser {
        bin: bin.clone(),
        b_seen: false,
        yaw: None,
        pitch: None,
        roll: None,
        inputs: Vec::new(),
        used_top: Vec::new(),
        in_image: false,
        img_b_seen: false,
        img_webify: None,
        img_height: None,
        img_width: None,
        img_yaw: None,
        img_pitch: None,
        img_roll: None,
        used_img: Vec::new(),
        empty_pending: Vec::new(),
        input_before_image: false,
    };

    let mut i = 0usize;
    let mut seen_dashdash = false;
    // Pending option that still needs a value from the next token.
    let mut pending: Option<ArgId> = None;

    while i < argv.len() {
        let tok = argv[i].clone();
        i += 1;

        if let Some(opt) = pending.take() {
            // Clap does not accept a value that looks like a flag.
            if is_flag_like(&tok) {
                // Option got no value; remember and reprocess this token.
                p.empty_pending.push(opt);
                // fall through to process tok as a fresh token
            } else {
                set_value(&mut p, opt, tok);
                continue;
            }
        }

        if seen_dashdash {
            if !p.in_image && (tok == "image" || tok == "help") && false {
                // handled below via positional path
            }
            push_positional(&mut p, &tok, true, &bin);
            continue;
        }

        if tok == "--" {
            seen_dashdash = true;
            continue;
        }

        if !p.in_image && tok == "help" {
            // help subcommand
            if i < argv.len() {
                let next = argv[i].clone();
                if next == "image" {
                    print!("{}", image_help(&bin, false));
                    exit(0);
                } else if next == "help" {
                    print!("{}", top_help(&bin));
                    exit(0);
                } else {
                    eprint!(
                        "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
                        next, bin
                    );
                    exit(1);
                }
            } else {
                print!("{}", top_help(&bin));
                exit(0);
            }
        }

        if !p.in_image && tok == "image" {
            p.in_image = true;
            p.input_before_image = !p.inputs.is_empty();
            continue;
        }

        if tok.starts_with("--") && tok.len() > 2 {
            // long flag
            let body = &tok[2..];
            let (name, inline_val) = match body.find('=') {
                Some(eq) => (&body[..eq], Some(body[eq + 1..].to_string())),
                None => (body, None),
            };
            match name {
                "help" => p.print_help(),
                "version" => p.print_version(),
                "yaw" | "pitch" | "roll" | "webify" => {
                    let opt = match name {
                        "yaw" => ArgId::Yaw,
                        "pitch" => ArgId::Pitch,
                        "roll" => ArgId::Roll,
                        _ => ArgId::Webify,
                    };
                    if opt == ArgId::Webify && !p.in_image {
                        p.unknown_arg(&tok);
                    }
                    check_dup(&p, opt);
                    mark_used(&mut p, opt);
                    if let Some(v) = inline_val {
                        set_value(&mut p, opt, v);
                    } else {
                        pending = Some(opt);
                    }
                }
                _ => {
                    // unknown long; check for a suggestion candidate
                    p.unknown_arg(&format!("--{}", name));
                }
            }
            continue;
        }

        if tok.starts_with('-') && tok.len() > 1 {
            // short cluster
            let chars: Vec<char> = tok[1..].chars().collect();
            let mut j = 0usize;
            let mut consumed_rest_as_value = false;
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    'h' if !p.in_image => {
                        p.print_help();
                    }
                    'V' => {
                        p.print_version();
                    }
                    'b' => {
                        let seen = if p.in_image { p.img_b_seen } else { p.b_seen };
                        if seen {
                            p.duplicate(ArgId::B);
                        }
                        if p.in_image {
                            p.img_b_seen = true;
                        } else {
                            p.b_seen = true;
                        }
                        mark_used(&mut p, ArgId::B);
                        j += 1;
                    }
                    'x' | 'y' | 'z' | 'w' | 'j' | 'h' => {
                        // option requiring a value ('h' reaches here only in image context: height)
                        let opt = match ch {
                            'x' => ArgId::Yaw,
                            'y' => ArgId::Pitch,
                            'z' => ArgId::Roll,
                            'w' => ArgId::Width,
                            'j' => ArgId::Webify,
                            _ => ArgId::Height,
                        };
                        if (opt == ArgId::Width || opt == ArgId::Webify || opt == ArgId::Height) && !p.in_image {
                            p.unknown_arg(&format!("-{}", ch));
                        }
                        check_dup(&p, opt);
                        mark_used(&mut p, opt);
                        // rest of cluster is the value
                        let rest: String = chars[j + 1..].iter().collect();
                        if !rest.is_empty() {
                            let v = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                            set_value(&mut p, opt, v);
                        } else {
                            pending = Some(opt);
                        }
                        consumed_rest_as_value = true;
                        break;
                    }
                    _ => {
                        p.unknown_arg(&format!("-{}", ch));
                    }
                }
            }
            let _ = consumed_rest_as_value;
            continue;
        }

        // positional (including "-" alone)
        push_positional(&mut p, &tok, false, &bin);
    }

    if let Some(opt) = pending.take() {
        p.empty_pending.push(opt);
    }

    // Validation phase.
    // 1. Missing required: subcommand (width) before parent (input).
    if p.in_image && p.img_width.is_none() && !p.used_img.contains(&ArgId::Width) {
        // width not supplied at all
        let usage = p.usage_for_error(ErrKind::MissingRequired, None);
        err_exit(
            "The following required arguments were not provided:\n    -w <width>".to_string(),
            usage,
        );
    }
    if p.in_image && p.img_width.is_none() && p.empty_pending.contains(&ArgId::Width) {
        // width supplied but empty -> falls through to empty-value handling below,
        // unless input is also missing? In clap, missing width error reported
        // was actually EmptyValue for `image -w`. Handle in empty-value phase.
    }
    if p.inputs.is_empty() && !p.in_image {
        let usage = p.usage_for_error(ErrKind::MissingRequired, None);
        err_exit(
            "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
            usage,
        );
    }
    if p.in_image && p.inputs.is_empty() {
        // If width also missing and there are used args, width error took precedence above.
        // If width is present (or empty-pending), parent-missing may still be reported
        // (clap reports missing input with top-level usage).
        if p.img_width.is_some() {
            err_exit(
                "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
                full_usage_top(&bin),
            );
        }
    }
    if p.in_image && p.img_width.is_none() {
        // Width missing entirely (used_img non-empty handled above; empty handled here), or empty-pending.
        if !p.empty_pending.contains(&ArgId::Width) {
            let usage = p.usage_for_error(ErrKind::MissingRequired, None);
            err_exit(
                "The following required arguments were not provided:\n    -w <width>".to_string(),
                usage,
            );
        }
    }
    if p.inputs.is_empty() && p.in_image {
        // width empty-pending but input missing: clap reports?
        // Fall through: empty-value for width will be reported below if input was provided;
        // if input missing, report missing input first? Observed `image -w 10` (width ok) -> missing input.
        // For `image -w` (width empty, input missing), observed behavior unknown; report missing input with top usage? 
        // We choose empty-value below.
    }
    // 2. Empty values.
    if let Some(opt) = p.empty_pending.first().copied() {
        // But if an empty-pending option is in the *other* context and a required
        // error above already fired, we do not reach here.
        err_exit(
            format!("The argument '{}' requires a value but none was supplied", arg_error_name(opt)),
            p.usage_for_error(ErrKind::EmptyValue, Some(opt)),
        );
    }
    if p.inputs.is_empty() {
        let usage = p.usage_for_error(ErrKind::MissingRequired, None);
        err_exit(
            "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
            usage,
        );
    }

    Matches {
        b: p.b_seen,
        yaw: p.yaw,
        pitch: p.pitch,
        roll: p.roll,
        inputs: p.inputs,
        image: if p.in_image {
            Some(ImageMatches {
                b: p.img_b_seen,
                webify: p.img_webify,
                height: p.img_height,
                width: p.img_width,
                yaw: p.img_yaw,
                pitch: p.img_pitch,
                roll: p.img_roll,
            })
        } else {
            None
        },
    }
}

fn is_flag_like(tok: &str) -> bool {
    tok.len() > 1 && tok.starts_with('-')
}

fn mark_used(p: &mut Parser, a: ArgId) {
    let list = if p.in_image { &mut p.used_img } else { &mut p.used_top };
    if !list.contains(&a) {
        list.push(a);
    }
}

fn check_dup(p: &Parser, a: ArgId) {
    let present = match (p.in_image, a) {
        (false, ArgId::Yaw) => p.yaw.is_some() || p.used_top.contains(&a) && p.yaw.is_some(),
        (false, ArgId::Pitch) => p.pitch.is_some(),
        (false, ArgId::Roll) => p.roll.is_some(),
        (true, ArgId::Yaw) => p.img_yaw.is_some(),
        (true, ArgId::Pitch) => p.img_pitch.is_some(),
        (true, ArgId::Roll) => p.img_roll.is_some(),
        (true, ArgId::Webify) => p.img_webify.is_some(),
        (true, ArgId::Height) => p.img_height.is_some(),
        (true, ArgId::Width) => p.img_width.is_some(),
        _ => false,
    };
    // For options given once with no value yet (pending), a second occurrence is also a duplicate in clap;
    // we approximate by checking used-with-value above, plus empty_pending.
    let pending_dup = p.empty_pending.contains(&a);
    if present || pending_dup {
        p.duplicate(a);
    }
}

fn set_value(p: &mut Parser, a: ArgId, v: String) {
    match (p.in_image, a) {
        (false, ArgId::Yaw) => p.yaw = Some(v),
        (false, ArgId::Pitch) => p.pitch = Some(v),
        (false, ArgId::Roll) => p.roll = Some(v),
        (true, ArgId::Yaw) => p.img_yaw = Some(v),
        (true, ArgId::Pitch) => p.img_pitch = Some(v),
        (true, ArgId::Roll) => p.img_roll = Some(v),
        (true, ArgId::Webify) => p.img_webify = Some(v),
        (true, ArgId::Height) => p.img_height = Some(v),
        (true, ArgId::Width) => p.img_width = Some(v),
        _ => {}
    }
}

fn push_positional(p: &mut Parser, tok: &str, after_dashdash: bool, bin: &str) {
    if after_dashdash && !p.in_image && (tok == "image" || tok == "help") {
        // Clap's special error when a subcommand name is used as a positional value after --.
        eprint!(
            "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",
            tok, tok, bin, tok,
            full_usage_top(bin)
        );
        exit(1);
    }
    if p.in_image {
        err_exit(
            format!("Found argument '{}' which wasn't expected, or isn't valid in this context", tok),
            p.usage_for_error(ErrKind::Unknown, None),
        );
    }
    p.inputs.push(tok.to_string());
}
EOF
echo done"}

{"command":"cat > src/inputs.rs <<'EOF'
use crate::cli::{ImageMatches, Matches};
use crate::geometry::Model;
use crate::{objload, stlload};
use std::path::Path;

pub struct Inputs {
    pub model: Model,
    pub scale: f32,
    pub rotation: (f32, f32, f32),
    pub color: bool,
}

pub type DynError = Box<dyn std::fmt::Debug>;

fn box_err<E: std::fmt::Debug + 'static>(e: E) -> DynError {
    Box::new(e)
}

#[derive(Debug)]
pub struct IoError(pub std::io::Error);

pub fn parse_rotation(
    x: &Option<String>,
    y: &Option<String>,
    z: &Option<String>,
) -> Result<(f32, f32, f32), DynError> {
    let xv = match x {
        Some(s) => s.parse::<f32>().map_err(box_err)?,
        None => 0.0,
    };
    let yv = match y {
        Some(s) => s.parse::<f32>().map_err(box_err)?,
        None => 0.0,
    };
    let zv = match z {
        Some(s) => s.parse::<f32>().map_err(box_err)?,
        None => 0.0,
    };
    Ok((xv, yv, zv))
}

fn load_model(filename: &str, model: &mut Model) -> Result<(), String> {
    let path = Path::new(filename);
    let ext = path.extension().map(|e| e.to_string_lossy().to_ascii_lowercase());
    match ext.as_deref() {
        Some("obj") => {
            let (raw, materials_result) = match objload::load_obj(path) {
                Ok(v) => v,
                Err(e) => {
                    return Err(format!(
                        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. {}",
                        filename, e
                    ));
                }
            };
            let materials = materials_result.expect("Expected to have materials.");
            model.add_obj_triangles(raw, &materials);
            Ok(())
        }
        Some("stl") => {
            match stlload::load_stl(path) {
                Ok(tris) => {
                    model.add_stl_triangles(tris);
                    Ok(())
                }
                Err(stlload::StlError::Open(e)) => Err(format!(
                    "filename: [{}] couldn't load, STL load failed. {}",
                    filename, e
                )),
                Err(stlload::StlError::Parse(e)) => Err(format!(
                    "filename: [{}] couldn't load, stl_io couldnt parse STL. {}",
                    filename, e
                )),
            }
        }
        Some(_) => Err(format!(
            "filename: [{}] couldn't load, unknown filename extension. ",
            filename
        )),
        None => Err(format!(
            "filename: [{}] couldn't load, couldn't determine filename extension. ",
            filename
        )),
    }
}

impl Inputs {
    pub fn new(matches: &Matches) -> Result<Inputs, DynError> {
        let first = matches.inputs.first().cloned().unwrap_or_default();
        let mut model = Model::new();
        for filename in first.split(' ') {
            load_model(filename, &mut model).unwrap();
        }
        let rotation = parse_rotation(&matches.yaw, &matches.pitch, &matches.roll)?;
        let scale = model.scale_factor();
        Ok(Inputs { model, scale, rotation, color: !matches.b })
    }
}

pub fn parse_image_options(
    image: &ImageMatches,
) -> Result<(usize, usize, (f32, f32, f32), Option<i32>), DynError> {
    let width: usize = image
        .width
        .as_ref()
        .unwrap()
        .parse()
        .map_err(box_err)?;
    let height: usize = match &image.height {
        Some(h) => h.parse().map_err(box_err)?,
        None => width,
    };
    let rotation = parse_rotation(&image.yaw, &image.pitch, &image.roll)?;
    let frames: Option<i32> = match &image.webify {
        Some(s) => Some(s.parse().map_err(box_err)?),
        None => None,
    };
    Ok((width, height, rotation, frames))
}
EOF
echo done"}

