// ---- terminal handling (termios via FFI, Linux) ----

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn tcgetattr(fd: i32, termios: *mut u8) -> i32;
    fn tcsetattr(fd: i32, action: i32, termios: *const u8) -> i32;
}

fn terminal_size() -> Result<(usize, usize), DynError> {
    let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let ret = unsafe { ioctl(0, 0x5413, &mut ws as *mut Winsize) };
    if ret != 0 {
        return Err(Box::new(IoError(io::Error::last_os_error())));
    }
    Ok((ws.ws_col as usize, ws.ws_row as usize))
}

struct RawGuard {
    original: [u8; 128],
}

impl RawGuard {
    fn new() -> Result<RawGuard, DynError> {
        let mut buf = [0u8; 128];
        let ret = unsafe { tcgetattr(0, buf.as_mut_ptr()) };
        if ret != 0 {
            return Err(Box::new(IoError(io::Error::last_os_error())));
        }
        let original = buf;
        // Make raw (termion-style): turn off canonical mode, echo, signals, etc.
        let mut raw = buf;
        let get32 = |b: &[u8; 128], off: usize| -> u32 {
            u32::from_ne_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]])
        };
        let put32 = |b: &mut [u8; 128], off: usize, v: u32| {
            b[off..off + 4].copy_from_slice(&v.to_ne_bytes());
        };
        // c_iflag at 0: clear IXON(0x400) ICRNL(0x100) BRKINT(0x2) INPCK(0x10) ISTRIP(0x20)
        let iflag = get32(&raw, 0) & !(0x400 | 0x100 | 0x2 | 0x10 | 0x20);
        put32(&mut raw, 0, iflag);
        // c_oflag at 4: clear OPOST(0x1)
        let oflag = get32(&raw, 4) & !0x1;
        put32(&mut raw, 4, oflag);
        // c_cflag at 8: set CS8(0x30)
        let cflag = get32(&raw, 8) | 0x30;
        put32(&mut raw, 8, cflag);
        // c_lflag at 12: clear ICANON(0x2) ECHO(0x8) ISIG(0x1) IEXTEN(0x8000)
        let lflag = get32(&raw, 12) & !(0x2 | 0x8 | 0x1 | 0x8000);
        put32(&mut raw, 12, lflag);
        let ret = unsafe { tcsetattr(0, 0, raw.as_ptr()) };
        if ret != 0 {
            return Err(Box::new(IoError(io::Error::last_os_error())));
        }
        Ok(RawGuard { original })
    }
}

impl Drop for RawGuard {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(0, 0, self.original.as_ptr());
        }
    }
}

#[derive(PartialEq)]
enum KeyAction {
    Quit,
    None,
}

struct KeyParser {
    buf: std::collections::VecDeque<u8>,
}

impl KeyParser {
    fn new() -> KeyParser {
        KeyParser { buf: std::collections::VecDeque::new() }
    }
    // Push a byte; returns Quit if a complete quit key was parsed.
    fn push(&mut self, b: u8) -> KeyAction {
        self.buf.push_back(b);
        self.parse(false)
    }
    // Called once per frame after draining available bytes: resolve a lone ESC.
    fn flush_esc(&mut self) -> KeyAction {
        self.parse(true)
    }
    fn parse(&mut self, _final: bool) -> KeyAction {
        loop {
            let Some(&b0) = self.buf.front() else { return KeyAction::None };
            if b0 == 0x03 {
                self.buf.pop_front();
                return KeyAction::Quit;
            }
            if b0 == b'q' {
                self.buf.pop_front();
                return KeyAction::Quit;
            }
            if b0 == 0x1b {
                // Need at least one more byte to decide; if none, wait for more input.
                if self.buf.len() < 2 {
                    return KeyAction::None;
                }
                let b1 = self.buf[1];
                if b1 == b'[' {
                    // CSI sequence: consume until final byte 0x40..=0x7e
                    let mut consumed = None;
                    for i in 2..self.buf.len() {
                        let c = self.buf[i];
                        if (0x40..=0x7e).contains(&c) {
                            consumed = Some(i + 1);
                            break;
                        }
                    }
                    match consumed {
                        Some(n) => {
                            for _ in 0..n { self.buf.pop_front(); }
                            continue;
                        }
                        None => return KeyAction::None,
                    }
                } else if b1 == b'O' {
                    if self.buf.len() < 3 {
                        return KeyAction::None;
                    }
                    for _ in 0..3 { self.buf.pop_front(); }
                    continue;
                } else {
                    // Alt + char (consume ESC and the following char's first byte).
                    self.buf.pop_front();
                    self.buf.pop_front();
                    continue;
                }
            }
            // Regular char (possibly UTF-8 lead byte): consume one char's worth.
            self.buf.pop_front();
            if b0 >= 0x80 {
                while let Some(&c) = self.buf.front() {
                    if c >= 0x80 && c < 0xc0 {
                        self.buf.pop_front();
                    } else {
                        break;
                    }
                }
            }
            // loop to parse next key; but only report quit (we returned above when found)
            // To avoid missing a quit key later in the buffer, continue loop.
            if self.buf.is_empty() {
                return KeyAction::None;
            }
        }
    }
}

fn interactive(inputs: &Inputs) -> Result<(), Box<dyn std::fmt::Debug>> {
    // Query size first so a non-tty stdin fails before any output.
    let _ = terminal_size()?;
    let _raw_guard = RawGuard::new()?;

    let (tx, rx) = mpsc::channel::<u8>();
    std::thread::spawn(move || {
        let stdin = io::stdin();
        let mut lock = stdin.lock();
        let mut buf = [0u8; 1024];
        loop {
            match lock.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    for b in &buf[..n] {
                        if tx.send(*b).is_err() {
                            return;
                        }
                    }
                }
                Err(_) => break,
            }
        }
    });

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    write!(out, "\x1b[?25l").map_err(|e| Box::new(IoError(e)) as DynError)?;

    let start = Instant::now();
    let mut parser = KeyParser::new();
    loop {
        let (cols, rows) = terminal_size()?;
        let mut rast = Rasterizer::new(cols, rows, inputs.color);
        let t = start.elapsed().as_secs_f32();
        let rot = (inputs.rotation.0, inputs.rotation.1 + t, inputs.rotation.2);
        rast.draw_model(&inputs.model.triangles, rot, inputs.scale);
        if inputs.color {
            write!(out, "\x1b[1;1H{}", rast.render_terminal_color())
                .map_err(|e| Box::new(IoError(e)) as DynError)?;
        } else {
            writeln!(out, "\x1b[1;1H{}", rast.render_terminal_plain())
                .map_err(|e| Box::new(IoError(e)) as DynError)?;
        }
        out.flush().map_err(|e| Box::new(IoError(e)) as DynError)?;

        let mut quit = false;
        while let Ok(b) = rx.try_recv() {
            if parser.push(b) == KeyAction::Quit {
                quit = true;
                break;
            }
        }
        if quit {
            break;
        }
    }
    write!(out, "\x1b[?25h").map_err(|e| Box::new(IoError(e)) as DynError)?;
    out.flush().map_err(|e| Box::new(IoError(e)) as DynError)?;
    Ok(())
}
